INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'pensioners-disability-grants-paid-earlier-november-2026-10-15',
  'Pensioners, disability grants to be paid earlier in November',
  'Community', '2026-10-15', 'SAnews', 'https://www.sanews.gov.za/node/84996',
  'Sassa moved its November grant payment dates earlier so pay-outs do not clash with the 4 November local government elections.',
  'Sassa has brought forward the November payment dates for several grants so that pay-outs do not fall in the same week as the 4 November local government elections. Older persons can collect their grant from Friday, 30 October. People receiving a disability grant get theirs from Monday, 2 November, and child support and other children''s grants follow on Tuesday, 3 November. Anyone whose grant is still being reviewed will be paid from Thursday, 5 November.

Sassa said it drew up the revised dates after talks with various stakeholders and with National Treasury''s sign-off, so that grant pay-outs continue smoothly and safely while the election period causes as little disruption as possible. The agency asked beneficiaries not to visit its offices unless necessary, since payments will follow the dates it has now published, and it urged anyone flagged for a review to reply to its messages and show up for review appointments when asked.',
  NULL, NULL, NULL,
  '["https://www.sanews.gov.za/node/84996", "https://www.ewn.co.za/2026/10/15/sassa-shifts-november-grant-payment-dates-ahead-of-local-government-elections"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'bulls-beat-stade-francais-56-20-champions-cup-2026-10-17',
  'Bulls crush Stade Francais 56-20 in Champions Cup opener',
  'Sport', '2026-10-17', 'TimesLIVE', 'https://www.timeslive.co.za/sport/2026-10-17-bulls-spank-pink-clad-stade-francais/',
  'The Bulls beat French side Stade Francais 56-20 at Loftus Versfeld on 17 October in their Investec Champions Cup opener.',
  'The Vodacom Bulls beat French side Stade Francais 56-20 at Loftus Versfeld on Saturday, 17 October, in their opening match of the Investec Champions Cup. Wing Cheswill Jooste opened the scoring about 20 seconds after kick-off, the second-fastest try in the competition''s history and only three seconds slower than the 17-second record set in 2013. The Bulls crossed the try line eight times in total, with Jooste adding two more tries later in the match and replacement forward Jeandre Rudolph also scoring.

Second-row Cameron Hanekom added another try shortly before the break, moving the score to 21-6. Stade Francais, who wore pink jerseys for the match, replied through 19-year-old lock Jacques Botha for their only try of the game. Two further Bulls tries were disallowed after review by the match officials, and wing Sebastian de Klerk was denied a try by inches despite a 50-metre chase. The match was played in temperatures of around 32 degrees Celsius.

The result gave the Bulls a bonus-point win in their Champions Cup opener and improved on their previous meeting with Stade Francais at Loftus, which the Bulls won 48-7.',
  NULL, NULL, NULL,
  '["https://www.timeslive.co.za/sport/2026-10-17-bulls-spank-pink-clad-stade-francais/", "https://www.rugbypass.com/live/bulls-vs-stade-francais/head-to-head/?g=293325"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'joburg-ballet-carmen-state-theatre-pretoria-2026-10-20',
  'Joburg Ballet brings Carmen to Pretoria''s State Theatre',
  'Community', '2026-10-20', 'Rekord', 'https://www.citizen.co.za/rekord/news-headlines/2026/10/20/former-principal-dancer-nicole-ferreira-dill-brings-paepers-carmen-to-pretoria-stage/',
  'Joburg Ballet stages two performances of its ballet Carmen at the State Theatre in Pretoria on 24 and 25 October.',
  'Dance company Joburg Ballet is bringing its production of Carmen to the capital for two shows. The venue is the South African State Theatre, with one performance on Saturday, 24 October, and a second on Sunday, 25 October, both getting underway at 15:00. Choreographed by Veronica Paeper and set to Georges Bizet''s music, the ballet is being revived to mark the company''s 25th anniversary and has not been staged by Joburg Ballet since 2018.

Savannah Jacobson and Mario Gaglione will dance the lead roles of Carmen and Don Jose on the Saturday, both making their debuts in the parts, while Latoya Mokoena and Miles Carrott take over for the Sunday performance. Former principal dancer Nicole Ferreira-Dill and ballet mistress Kim Vieira, who both performed Paeper''s choreography during their own careers, have been helping guide the current dancers through the production.

Joburg Ballet artistic director Dane Hurst said the ballet''s mix of classical and Spanish-inspired movement explores themes of desire, tragedy and a woman living life on her own terms. These Pretoria dates come after a run of shows in Johannesburg, and tickets are available through Webtickets.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/rekord/news-headlines/2026/10/20/former-principal-dancer-nicole-ferreira-dill-brings-paepers-carmen-to-pretoria-stage/", "https://pretorianews.co.za/saturday-star/2026-10-17-joburg-ballets-carmen-heads-to-pretoria-for-two-performances/"]',
  'agent'
);
